CREATE UNIQUE INDEX "command_audit_log_derivative_rebuild_terminal_uidx" ON "public"."command_audit_log" USING "btree" ("actor_user_id", (("payload" ->> 'request_id'::"text"))) WHERE (("command" = 'cmd_dataset_derivative_rebuild_terminal'::"text") AND ("target_table" = ANY (ARRAY['flows'::"text", 'processes'::"text"])) AND (("payload" ->> 'record_type'::"text") = 'terminal'::"text"));
